-- Shared source selectors preserve list response mappings and public signatures.
create function public.m14_03_connector_registry_rows(p_org uuid) returns setof public.connectors
language sql stable security definer set search_path=public,pg_temp as $$ select c.* from public.connectors c where c.organization_id=p_org and c.archived_at is null $$;
create function public.m14_03_connector_identity_rows(p_org uuid,p_connector uuid) returns setof public.product_external_identities
language sql stable security definer set search_path=public,pg_temp as $$ select c.* from public.product_external_identities c where c.organization_id=p_org and c.connector_id=p_connector and c.superseded_at is null $$;
create function public.m14_03_connector_run_rows(p_org uuid,p_connector uuid,p_status text default null) returns setof public.sync_runs
language sql stable security definer set search_path=public,pg_temp as $$ select c.* from public.sync_runs c where c.organization_id=p_org and c.connector_id=p_connector and (p_status is null or c.status=p_status) $$;
create function public.m14_03_connector_plan_rows(p_org uuid,p_run uuid) returns setof public.sync_run_plan_items
language sql stable security definer set search_path=public,pg_temp as $$ select c.* from public.sync_run_plan_items c where c.organization_id=p_org and c.sync_run_id=p_run $$;
create function public.m14_03_connector_conflict_rows(p_org uuid,p_run uuid) returns setof public.sync_conflicts
language sql stable security definer set search_path=public,pg_temp as $$ select c.* from public.sync_conflicts c where c.organization_id=p_org and c.sync_run_id=p_run $$;
create function public.m14_03_framework_pack_rows(p_org uuid) returns setof public.framework_pack_versions
language sql stable security definer set search_path=public,pg_temp as $$ select c.* from public.framework_pack_versions c where c.owner_org_id is null or c.owner_org_id=p_org $$;
create function public.m14_03_framework_control_rows(p_org uuid,p_include_archived boolean default false) returns setof public.framework_controls
language sql stable security definer set search_path=public,pg_temp as $$ select c.* from public.framework_controls c where c.organization_id=p_org and (p_include_archived or c.archived_at is null) $$;
create function public.m14_03_legal_entity_rows(p_org uuid) returns setof public.organization_legal_entities
language sql stable security definer set search_path=public,pg_temp as $$ select c.* from public.organization_legal_entities c where c.organization_id=p_org and c.status<>'deleted' $$;
-- Reuse the selector inside the existing source facade; no signature, outcome, or row mapping changes.
do $legal$ declare v_def text;begin
 v_def:=pg_get_functiondef('public.get_organization_legal_entities(uuid,uuid)'::regprocedure);
 if position('from public.organization_legal_entities entities' in v_def)=0 then raise exception 'legal_entity_list_baseline_changed';end if;
 v_def:=replace(v_def,'from public.organization_legal_entities entities','from public.m14_03_legal_entity_rows(p_organization_id) entities');
 execute v_def;
end $legal$;

-- M14-03 source-owned operational projections. All helpers share one STABLE statement snapshot.
-- JSON object whitelists below intentionally exclude credentials, storage paths and arbitrary provider payloads.
alter function public.m14_03_source_policy(text) rename to m14_03_core_source_policy;
create function public.m14_03_source_policy(p_source text) returns jsonb language sql immutable
set search_path=public,pg_temp as $$ select case p_source
when 'connectors.instances' then '{"permissions":["can_view_connectors","can_export_connectors"],"columns":["id","displayName","connectorType","adapterVersion","mappingVersion","commitPolicy","enabled","hasSecret","lastTestedAt","lastTestOutcome","lastTestErrorCode","version","createdAt","updatedAt"],"page":true}'::jsonb
when 'connectors.identities' then '{"permissions":["can_view_connectors","can_export_connectors"],"columns":["id","connectorId","externalId","entityType","craProductId","craReleaseId","linkedAt"],"page":true}'::jsonb
when 'connectors.sync_runs' then '{"permissions":["can_view_connectors","can_export_connectors"],"columns":["id","connectorId","status","reconciliationKind","workKind","adapterVersion","mappingVersion","rowCount","errorCode","retryCount","expiresAt","committedAt","canceledAt","createdAt","updatedAt"],"page":true}'::jsonb
when 'connectors.dead_letters' then '{"permissions":["can_view_connectors","can_export_connectors"],"columns":["id","connectorId","status","reconciliationKind","workKind","adapterVersion","mappingVersion","rowCount","errorCode","retryCount","expiresAt","committedAt","canceledAt","createdAt","updatedAt"],"page":true}'::jsonb
when 'connectors.sync_history' then '{"permissions":["can_view_connectors","can_export_connectors"],"columns":["id","connectorId","status","reconciliationKind","workKind","adapterVersion","mappingVersion","rowCount","errorCode","retryCount","expiresAt","committedAt","canceledAt","createdAt","updatedAt","startedAt","finishedAt","version","fieldMappingRevision","replayOfRunId","succeededCount","skippedCount","failedCount","pendingCount","retryAt"],"page":true}'::jsonb
when 'connectors.sync_records' then '{"permissions":["can_view_connectors","can_export_connectors"],"columns":["id","runId","externalId","entityType","proposedAction","outcome","errorCategory","errorCode","deadLetteredAt","appliedAt"],"page":true}'::jsonb
when 'connectors.sync_plan_items' then '{"permissions":["can_view_connectors","can_export_connectors"],"columns":["id","runId","externalId","entityType","proposedAction","outcome","errorCategory","errorCode","deadLetteredAt","appliedAt","craProductId","craReleaseId","expectedVersion","createdAt"],"page":true}'::jsonb
when 'connectors.dead_letter_records' then '{"permissions":["can_view_connectors","can_export_connectors"],"columns":["id","runId","externalId","entityType","proposedAction","outcome","errorCategory","errorCode","deadLetteredAt","appliedAt"],"page":true}'::jsonb
when 'connectors.run_conflicts' then '{"permissions":["can_view_connectors","can_export_connectors"],"columns":["id","syncRunId","entityType","entityId","fieldPath","conflictKind","resolutionStatus","resolutionChosenAction","resolutionReason","resolvedBy","resolvedAt","detectedAt","version"],"page":false}'::jsonb
when 'connectors.sync_run_attempts' then '{"permissions":["can_view_connectors","can_export_connectors"],"columns":["id","runId","generation","phase","startedAt","finishedAt","outcome","errorCategory","errorCode","nextAttemptAt"],"page":true}'::jsonb
when 'connectors.agent_batches' then '{"permissions":["can_view_connectors","can_export_connectors"],"columns":["id","sequence","recordCount","receivedAt","status"],"page":false}'::jsonb
when 'connectors.webhook_endpoints' then '{"permissions":["can_view_connectors","can_export_connectors"],"columns":["id","displayName","enabled","hasSecret","version","scopeRevision","destinationRevision","createdAt","updatedAt"],"page":true}'::jsonb
when 'connectors.webhook_deliveries' then '{"permissions":["can_view_connectors","can_export_connectors"],"columns":["id","endpointId","eventId","deliveryId","eventType","status","occurredAt","nextAttemptAt","attemptCount","lastHttpStatus","lastFailureCategory","lastFailureCode","version","deadlineAt","completedAt","createdAt","updatedAt"],"page":true}'::jsonb
when 'connectors.webhook_attempts' then '{"permissions":["can_view_connectors","can_export_connectors"],"columns":["id","deliveryRowId","attemptNumber","leaseGeneration","startedAt","finishedAt","outcome","httpStatus","durationMs","failureCategory","failureCode","responseBytes"],"page":true}'::jsonb
when 'connectors.siem_destinations' then '{"permissions":["can_view_connectors","can_export_connectors","can_view_audit","can_export_audit"],"columns":["id","name","transport","format","state","version","credentialState","authorityUserId","createdAt","updatedAt"],"page":false}'::jsonb
when 'connectors.siem_deliveries' then '{"permissions":["can_view_connectors","can_export_connectors","can_view_audit","can_export_audit"],"columns":["id","destinationId","eventId","destinationRevision","state","attemptCount","nextAttemptAt","safeFailureCode","parentDeliveryId","createdAt","updatedAt"],"page":false}'::jsonb
when 'connectors.catalogue' then '{"permissions":["can_view_connectors","can_export_connectors"],"columns":["id","name","implementation","phase","priority","canConfigure","description","guidance","scopePolicyVersion","requiredScopes","scopeIntrospection"],"page":false}'::jsonb
when 'connectors.overview' then '{"permissions":["can_view_connectors","can_export_connectors"],"columns":["id","displayName","connectorType","enabled","version","createdAt","updatedAt","status","lastSyncAt"],"page":false}'::jsonb
when 'frameworks.catalog' then '{"permissions":["can_view_frameworks","can_export_frameworks"],"columns":["packKey","versionKey","title","editionDate","language","sourceUrl","sourceReference","attribution","contentHash","sourceKind","editionLabel","distributionRights","reviewOwner","selected","enabled","selectionRevision"],"page":false}'::jsonb
when 'frameworks.requirement_tree' then '{"permissions":["can_view_frameworks","can_export_frameworks"],"columns":["requirementKey","identifier","parentKey","position","depth","heading","text","sourceReference"],"page":false}'::jsonb
when 'frameworks.controls' then '{"permissions":["can_view_frameworks","can_export_frameworks"],"columns":["id","title","description","ownerUserId","ownerActive","status","revision","archivedAt","createdAt","updatedAt"],"page":false}'::jsonb
when 'frameworks.crosswalks' then '{"permissions":["can_view_frameworks","can_export_frameworks"],"columns":["id","source","target","relationship","direction","rationale","provenance","reviewer","reviewedAt","curated"],"page":false}'::jsonb
when 'frameworks.upgrade_preview' then '{"permissions":["can_view_frameworks","can_export_frameworks","can_view_products","can_view_evidence","can_manage_frameworks"],"columns":["mappingId","controlId","controlRevision","sourceRequirementKey","productIds","evidenceVersionIds","suggestedTargetKeys"],"page":false}'::jsonb
when 'frameworks.upgrade_review' then '{"permissions":["can_view_frameworks","can_export_frameworks","can_view_products","can_view_evidence","can_manage_frameworks"],"columns":["mappingId","action","targetRequirementKeys"],"page":false}'::jsonb
when 'frameworks.custom' then '{"permissions":["can_view_frameworks","can_export_frameworks"],"columns":["draftId","packKey","title","status","revision","latestVersionKey","selectedVersionKey","contentHash","archivedAt","updatedAt"],"page":false}'::jsonb
when 'frameworks.custom_requirements_preview' then '{"permissions":["can_view_frameworks","can_export_frameworks"],"columns":["requirementKey","identifier","parentKey","position","depth","heading","text","sourceReference"],"page":false}'::jsonb
when 'notifications.feed' then '{"permissions":["can_export_notifications"],"columns":["ref","category","severity","occurredAt","title","summary","read","fingerprint","sourceState","noticeKind","kind","eventClass","windowStartsAt","windowEndsAt","visibleCount","unreadCount","previewCount","previewTruncated"],"page":false}'::jsonb
when 'notifications.feed_preview_items' then '{"permissions":["can_export_notifications"],"columns":["ref","category","severity","occurredAt","title","summary","read","fingerprint","sourceState","noticeKind","kind","eventClass","windowStartsAt","windowEndsAt","visibleCount","unreadCount","previewCount","previewTruncated"],"page":false}'::jsonb
when 'notifications.deliveries' then '{"permissions":["can_export_notifications","can_view_audit"],"columns":["deliveryRef","category","status","sourceType","sourceId","originalRecipientUserId","effectiveRecipientUserId","attemptCount","lastAttemptAt","nextAttemptAt","safeErrorCode","createdAt","updatedAt","version"],"page":false}'::jsonb
when 'notifications.burst_batches' then '{"permissions":["can_export_notifications","can_view_audit"],"columns":["batchId","category","eventClass","status","windowStartsAt","windowEndsAt","memberCount","preparedCount","attemptCount","lastAttemptAt","nextAttemptAt","safeErrorCode","createdAt"],"page":false}'::jsonb
when 'notifications.chat_channels' then '{"permissions":["can_export_notifications","can_edit_organization"],"columns":["id","mode","displayName","enabled","verified","version","eventClasses","productIds","includeOrganizationWide","safeErrorCode","createdAt","updatedAt"],"page":false}'::jsonb
when 'notifications.chat_deliveries' then '{"permissions":["can_export_notifications","can_view_audit"],"columns":["id","channelId","eventClass","status","sourceType","sourceId","sourceRevision","attemptCount","lastAttemptAt","nextAttemptAt","safeErrorCode","createdAt","updatedAt","version"],"page":false}'::jsonb
when 'organization.legal_entities' then '{"permissions":["can_view_organization","can_export_organization"],"columns":["id","identifier","displayName","legalName","mainEstablishmentCountry","manufacturerContactName","manufacturerContactEmail","phone","registrationIdentifier","taxIdentifier","completionStatus","status","isDefault","version","createdAt","updatedAt"],"page":false}'::jsonb
when 'organization.retention_policies' then '{"permissions":["can_view_organization","can_export_organization"],"columns":["id","evidenceClass","version","requestedRetentionDays","effectiveFloorDays","effectiveRetentionDays","floorSnapshotVersion","updatedAt"],"page":false}'::jsonb
when 'organization.tenant_exports' then '{"permissions":["can_view_organization","can_export_organization"],"columns":["id","status","completedParts","totalParts","attemptCount","safeErrorCode","verifiedAt","createdAt","updatedAt"],"page":false}'::jsonb
when 'organization.holidays' then '{"permissions":["can_view_organization","can_export_organization"],"columns":["date"],"page":false}'::jsonb
when 'organization.lifecycle_blockers' then '{"permissions":["can_view_organization","can_export_organization"],"columns":["kind","code","recordId","requiredRetentionDays"],"page":false}'::jsonb
when 'onboarding.progress' then '{"permissions":["can_view_organization","can_export_organization"],"columns":["stage","status","blockReason","completedAt","completedBy","updatedAt"],"page":false}'::jsonb
when 'permissions.matrix' then '{"permissions":["can_view_roles","can_export_roles"],"columns":["permissionKey","owner","admin","member","viewer"],"page":false}'::jsonb
when 'frameworks.coverage_requirements' then '{"permissions":["can_view_frameworks","can_export_frameworks","can_view_products","can_view_evidence"],"columns":["requirementKey","identifier","heading","text","parentKey","coverageState","calculationStatus","sourceRevision","computedRevision"],"page":false}'::jsonb
else public.m14_03_core_source_policy(p_source) end $$;

-- Group completeness is bound to every currently authorized member, not just the five preview items.
create function public.m14_03_feed_group_scope(p_org uuid,p_actor uuid,p_class text,p_window timestamptz,p_category text,p_severity text,p_as_of timestamptz default statement_timestamp())
returns text language plpgsql stable security definer set search_path=public,pg_temp as $$
declare v_count bigint;v_digest text;
begin
 select count(*),encode(extensions.digest(coalesce(string_agg(f.ref||':'||f.fingerprint,'|' order by f.ref),''),'sha256'),'hex')
 into v_count,v_digest from (
 select f.ref,f.fingerprint from public.m12_06_feed_rows(p_org,p_actor) f
 where public.m12_06_feed_event_class(f.ref,f.summary)=p_class and f.category=p_category
 and date_bin(interval '2 minutes',f.source_created_at,'2000-01-01'::timestamptz)=p_window
 and f.source_created_at<=p_as_of
 and f.occurred_at<=p_as_of
 and f.notice_kind='event' and f.severity in ('info','warning')
 and (p_severity is null or f.severity=p_severity)
 order by f.ref limit 100001) f;
 if v_count>100000 then raise exception 'export_row_limit' using errcode='54000';end if;
 return v_digest;
end $$;
create function public.m14_03_operational_projection(p_row jsonb,p_keys jsonb) returns jsonb
language sql immutable set search_path=public,pg_temp as $$
 select coalesce(jsonb_object_agg(k.value,case when jsonb_typeof(p_row->k.value) in ('object','array')
 then to_jsonb((p_row->k.value)::text) else coalesce(p_row->k.value,'null'::jsonb) end),'{}'::jsonb)
 from jsonb_array_elements_text(p_keys) k(value)
$$;
create function public.m14_03_operational_source_rows_unprojected(p_org uuid,p_actor uuid,p_source text,p_filters jsonb,p_context jsonb)
returns table(source_id text,source_version text,product_id uuid,row_values jsonb)
language plpgsql stable security definer set search_path=public,pg_temp as $$
declare v_policy jsonb; v_permission text; v_connector uuid; v_run uuid; v_endpoint uuid; v_delivery uuid;
 v_destination uuid; v_product uuid; v_outcome text; v_result jsonb; v_cursor text; v_next text;
 v_offset integer:=0; v_total integer:=0; v_item jsonb; v_keys jsonb; v_id text;
begin
 v_policy:=public.m14_03_source_policy(p_source);
 if v_policy is null then raise exception 'export_unsupported_source' using errcode='22023'; end if;
 if not public.m1201_active_member(p_org,p_actor) then raise exception 'export_access_denied' using errcode='42501'; end if;
 for v_permission in select jsonb_array_elements_text(v_policy->'permissions') loop
  if not public.m14_03_actor_can(p_org,p_actor,v_permission) then raise exception 'export_access_denied' using errcode='42501'; end if;
 end loop;
 if p_source in ('organization.tenant_exports') and not exists(select 1 from public.organization_members m where m.organization_id=p_org and m.user_id=p_actor and m.role='owner') then raise exception 'export_access_denied' using errcode='42501'; end if;
 if p_source='notifications.chat_channels' and not public.m12_05_chat_admin(p_org,p_actor) then raise exception 'export_access_denied' using errcode='42501'; end if;
 v_connector:=(p_context->>'connectorId')::uuid; v_run:=(p_context->>'syncRunId')::uuid;
 v_endpoint:=(p_context->>'endpointId')::uuid; v_delivery:=(p_context->>'deliveryId')::uuid;
 v_destination:=(p_context->>'destinationId')::uuid; v_product:=coalesce((p_context->>'productId')::uuid,(p_filters->>'productId')::uuid);
 if p_source in ('connectors.identities','connectors.sync_runs','connectors.dead_letters','connectors.sync_history','connectors.sync_records','connectors.sync_plan_items','connectors.run_conflicts','connectors.sync_run_attempts','connectors.dead_letter_records','connectors.agent_batches') then
  if v_connector is null or not exists(select 1 from public.connectors c where c.organization_id=p_org and c.id=v_connector) then raise exception 'export_context_not_found' using errcode='P0002'; end if;
 end if;
 if p_source in ('connectors.sync_records','connectors.sync_plan_items','connectors.run_conflicts','connectors.sync_run_attempts') and (v_run is null or not exists(select 1 from public.sync_runs r where r.organization_id=p_org and r.connector_id=v_connector and r.id=v_run)) then raise exception 'export_context_not_found' using errcode='P0002'; end if;
 if p_source in ('connectors.webhook_deliveries','connectors.webhook_attempts') and (v_endpoint is null or not exists(select 1 from public.webhook_endpoints e where e.organization_id=p_org and e.id=v_endpoint)) then raise exception 'export_context_not_found' using errcode='P0002'; end if;
 if p_source='connectors.webhook_attempts' and (v_delivery is null or not exists(select 1 from public.webhook_deliveries d where d.organization_id=p_org and d.endpoint_id=v_endpoint and d.id=v_delivery)) then raise exception 'export_context_not_found' using errcode='P0002'; end if;
 if p_source='connectors.siem_deliveries' and (v_destination is null or not exists(select 1 from public.siem_destinations d where d.organization_id=p_org and d.id=v_destination)) then raise exception 'export_context_not_found' using errcode='P0002'; end if;
 if p_source='frameworks.coverage_requirements' and (v_product is null or not exists(select 1 from public.products p where p.organization_id=p_org and p.id=v_product and p.archived_at is null)) then raise exception 'export_context_not_found' using errcode='P0002'; end if;
 v_keys:=v_policy->'columns';
 if p_context->>'_exportScope'='current_page' then v_cursor:=p_filters->>'cursor'; end if;
 case p_source
when 'connectors.instances' then
 return query select r.id::text, encode(extensions.digest((jsonb_build_object('id',r.id,'displayName',r.display_name,'connectorType',r.connector_type,'adapterVersion',r.adapter_version,'mappingVersion',r.mapping_version,'commitPolicy',r.commit_policy,'enabled',r.enabled,'hasSecret',r.secret_ref is not null,'lastTestedAt',r.last_tested_at,'lastTestOutcome',r.last_test_outcome,'lastTestErrorCode',r.last_test_error_code,'version',r.version,'createdAt',r.created_at,'updatedAt',r.updated_at))::text,'sha256'),'hex'),null::uuid,jsonb_build_object('id',r.id,'displayName',r.display_name,'connectorType',r.connector_type,'adapterVersion',r.adapter_version,'mappingVersion',r.mapping_version,'commitPolicy',r.commit_policy,'enabled',r.enabled,'hasSecret',r.secret_ref is not null,'lastTestedAt',r.last_tested_at,'lastTestOutcome',r.last_test_outcome,'lastTestErrorCode',r.last_test_error_code,'version',r.version,'createdAt',r.created_at,'updatedAt',r.updated_at) from public.m14_03_connector_registry_rows(p_org) r  where r.organization_id=p_org  order by r.created_at desc,r.id limit 100001; return;
when 'connectors.identities' then
 return query select r.id::text, encode(extensions.digest((jsonb_build_object('id',r.id,'connectorId',r.connector_id,'externalId',r.external_id,'entityType',r.entity_type,'craProductId',r.cra_product_id,'craReleaseId',r.cra_release_id,'linkedAt',r.linked_at))::text,'sha256'),'hex'),null::uuid,jsonb_build_object('id',r.id,'connectorId',r.connector_id,'externalId',r.external_id,'entityType',r.entity_type,'craProductId',r.cra_product_id,'craReleaseId',r.cra_release_id,'linkedAt',r.linked_at) from public.m14_03_connector_identity_rows(p_org,v_connector) r  where r.organization_id=p_org  order by r.linked_at desc,r.id limit 100001; return;
when 'connectors.sync_runs' then
 return query select r.id::text, encode(extensions.digest((jsonb_build_object('id',r.id,'connectorId',r.connector_id,'status',r.status,'reconciliationKind',r.reconciliation_kind,'workKind',r.work_kind,'adapterVersion',r.adapter_version,'mappingVersion',r.mapping_version,'rowCount',r.row_count,'errorCode',r.error_code,'retryCount',r.retry_count,'expiresAt',r.expires_at,'committedAt',r.committed_at,'canceledAt',r.canceled_at,'createdAt',r.created_at,'updatedAt',r.updated_at))::text,'sha256'),'hex'),null::uuid,jsonb_build_object('id',r.id,'connectorId',r.connector_id,'status',r.status,'reconciliationKind',r.reconciliation_kind,'workKind',r.work_kind,'adapterVersion',r.adapter_version,'mappingVersion',r.mapping_version,'rowCount',r.row_count,'errorCode',r.error_code,'retryCount',r.retry_count,'expiresAt',r.expires_at,'committedAt',r.committed_at,'canceledAt',r.canceled_at,'createdAt',r.created_at,'updatedAt',r.updated_at) from public.m14_03_connector_run_rows(p_org,v_connector,p_filters->>'status') r  where r.organization_id=p_org and r.connector_id=v_connector and (p_filters->>'status' is null or r.status=p_filters->>'status') order by r.created_at desc,r.id limit 100001; return;
when 'connectors.dead_letters' then
 return query select r.id::text, encode(extensions.digest((jsonb_build_object('id',r.id,'connectorId',r.connector_id,'status',r.status,'reconciliationKind',r.reconciliation_kind,'workKind',r.work_kind,'adapterVersion',r.adapter_version,'mappingVersion',r.mapping_version,'rowCount',r.row_count,'errorCode',r.error_code,'retryCount',r.retry_count,'expiresAt',r.expires_at,'committedAt',r.committed_at,'canceledAt',r.canceled_at,'createdAt',r.created_at,'updatedAt',r.updated_at))::text,'sha256'),'hex'),null::uuid,jsonb_build_object('id',r.id,'connectorId',r.connector_id,'status',r.status,'reconciliationKind',r.reconciliation_kind,'workKind',r.work_kind,'adapterVersion',r.adapter_version,'mappingVersion',r.mapping_version,'rowCount',r.row_count,'errorCode',r.error_code,'retryCount',r.retry_count,'expiresAt',r.expires_at,'committedAt',r.committed_at,'canceledAt',r.canceled_at,'createdAt',r.created_at,'updatedAt',r.updated_at) from public.m14_03_connector_run_rows(p_org,v_connector,'failed') r  where r.organization_id=p_org and r.connector_id=v_connector and r.status='failed' order by r.created_at desc,r.id limit 100001; return;
when 'connectors.sync_history' then
 return query select r.id::text, encode(extensions.digest((jsonb_build_object('id',r.id,'connectorId',r.connector_id,'status',r.status,'reconciliationKind',r.reconciliation_kind,'workKind',r.work_kind,'adapterVersion',r.adapter_version,'mappingVersion',r.mapping_version,'rowCount',r.row_count,'errorCode',r.error_code,'retryCount',r.retry_count,'expiresAt',r.expires_at,'committedAt',r.committed_at,'canceledAt',r.canceled_at,'createdAt',r.created_at,'updatedAt',r.updated_at,'startedAt',r.started_at,'finishedAt',r.finished_at,'version',r.version,'fieldMappingRevision',r.field_mapping_revision,'replayOfRunId',r.replay_parent_run_id,'succeededCount',r.succeeded_count,'skippedCount',r.skipped_count,'failedCount',r.failed_count,'pendingCount',r.pending_count,'retryAt',r.next_attempt_at))::text,'sha256'),'hex'),null::uuid,jsonb_build_object('id',r.id,'connectorId',r.connector_id,'status',r.status,'reconciliationKind',r.reconciliation_kind,'workKind',r.work_kind,'adapterVersion',r.adapter_version,'mappingVersion',r.mapping_version,'rowCount',r.row_count,'errorCode',r.error_code,'retryCount',r.retry_count,'expiresAt',r.expires_at,'committedAt',r.committed_at,'canceledAt',r.canceled_at,'createdAt',r.created_at,'updatedAt',r.updated_at,'startedAt',r.started_at,'finishedAt',r.finished_at,'version',r.version,'fieldMappingRevision',r.field_mapping_revision,'replayOfRunId',r.replay_parent_run_id,'succeededCount',r.succeeded_count,'skippedCount',r.skipped_count,'failedCount',r.failed_count,'pendingCount',r.pending_count,'retryAt',r.next_attempt_at) from public.m14_03_connector_run_rows(p_org,v_connector,null) r  where r.organization_id=p_org and r.connector_id=v_connector order by r.created_at desc,r.id desc limit 100001; return;
when 'connectors.sync_records' then
