when 'connectors.overview' then
 return query select c.id::text,c.version::text,null::uuid,jsonb_build_object('id',c.id,'displayName',c.display_name,'connectorType',c.connector_type,'enabled',c.enabled,'version',c.version,'createdAt',c.created_at,'updatedAt',c.updated_at,'status',case when not c.enabled or s.credential_revoked or c.secret_ref is null or s.last_test_connection_revision is distinct from s.connection_revision then 'not_connected' when s.scope_assessment->>'status'='missing' then 'degraded' when c.last_test_error_code='auth_failed' then 'auth_expired' when c.last_test_outcome is distinct from 'success' then 'degraded' when s.active_sync_status='running' then 'syncing' else 'healthy' end,'lastSyncAt',s.last_sync_at) from public.connectors c cross join lateral public.m11_connector_connection_summaries(p_org,array[c.id]) s where c.organization_id=p_org and c.archived_at is null order by c.created_at desc,c.id limit 100001; return;
when 'frameworks.catalog' then
 return query select r.pack_key||':'||r.version_key,r.content_hash,null::uuid,jsonb_build_object('packKey',r.pack_key,'versionKey',r.version_key,'title',r.title,'editionDate',r.edition_date,'language',r.language,'sourceUrl',r.source_url,'sourceReference',case when r.source_kind='customer_defined' then 'Customer-defined requirements' when r.source_celex is not null then 'CELEX:'||r.source_celex else coalesce(r.edition_label,r.source_url,'Reviewed framework') end,'attribution',r.attribution,'contentHash',r.content_hash,'sourceKind',r.source_kind,'editionLabel',r.edition_label,'distributionRights',r.distribution_rights,'reviewOwner',r.review_owner,'selected',s.version_key=r.version_key,'enabled',s.enabled,'selectionRevision',s.revision) from public.m14_03_framework_pack_rows(p_org) r left join public.organization_framework_selections s on s.organization_id=p_org and s.pack_key=r.pack_key order by r.pack_key,r.edition_date desc,r.version_key limit 100001; return;
