 return query select r.id::text, encode(extensions.digest((jsonb_build_object('id',r.id,'title',r.title,'description',r.description,'ownerUserId',r.owner_user_id,'ownerActive',exists(select 1 from public.organization_members m join public.users u on u.id=m.user_id and u.is_active where m.organization_id=p_org and m.user_id=r.owner_user_id),'status',r.implementation_status,'revision',r.revision,'archivedAt',r.archived_at,'createdAt',r.created_at,'updatedAt',r.updated_at))::text,'sha256'),'hex'),null::uuid,jsonb_build_object('id',r.id,'title',r.title,'description',r.description,'ownerUserId',r.owner_user_id,'ownerActive',exists(select 1 from public.organization_members m join public.users u on u.id=m.user_id and u.is_active where m.organization_id=p_org and m.user_id=r.owner_user_id),'status',r.implementation_status,'revision',r.revision,'archivedAt',r.archived_at,'createdAt',r.created_at,'updatedAt',r.updated_at) from public.m14_03_framework_control_rows(p_org,coalesce((p_filters->>'includeArchived')::boolean,false)) r  where r.organization_id=p_org and (coalesce((p_filters->>'includeArchived')::boolean,false) or r.archived_at is null) order by r.updated_at desc,r.id limit 100001; return;
when 'frameworks.crosswalks' then
 loop
  select outcome,result into v_outcome,v_result from public.m10_crosswalk_page(p_org,p_actor,p_context->>'packKey',p_context->>'versionKey',100,v_offset);
  if v_outcome not in ('found','listed','previewed','ok') or v_result is null then raise exception 'export_source_%',coalesce(v_outcome,'unavailable') using errcode='42501'; end if;
  for v_item in select jsonb_array_elements(coalesce(v_result->'relations','[]'::jsonb)) loop
   v_total:=v_total+1; if v_total>100001 or (p_source='notifications.feed_preview_items' and v_total>5) then return; end if;
   v_id:=coalesce(v_item->>'id','batch|'||(v_item->>'eventClass')||'|'||(v_item->>'windowStartsAt')||'|'||(v_item->>'category')||'|'||coalesce(p_filters->>'severity',''));
   if v_id is null then raise exception 'export_invalid_source_identity' using errcode='22023'; end if;
   source_id:=v_id; source_version:=case when p_source='notifications.feed_preview_items' then public.m14_03_feed_group_scope(p_org,p_actor,p_context->>'eventClass',(p_context->>'windowStartsAt')::timestamptz,v_item->>'category',p_filters->>'severity') when v_item->>'kind'='batch' then public.m14_03_feed_group_scope(p_org,p_actor,v_item->>'eventClass',(v_item->>'windowStartsAt')::timestamptz,v_item->>'category',p_filters->>'severity') else encode(extensions.digest(v_item::text,'sha256'),'hex') end; product_id:=null; row_values:=public.m14_03_operational_projection(v_item,v_keys); return next;
  end loop;
  v_next:=v_result->>'nextCursor'; if v_next is null then exit; end if;
  if v_cursor=v_next then raise exception 'export_source_cursor_cycle' using errcode='22023'; end if;
  v_cursor:=v_next; v_offset:=v_offset+100;
  if v_total>=100001 then exit; end if;
 end loop; return;
