when 'notifications.feed' then
 loop
  if p_filters->>'view'='grouped' then select outcome,result into v_outcome,v_result from public.list_notification_feed_grouped_atomic(p_org,p_actor,p_filters->>'category',p_filters->>'severity',coalesce(p_filters->>'read','all'),v_cursor,50); elsif p_filters->>'batchId' is not null or p_filters->>'eventClass' is not null then select outcome,result into v_outcome,v_result from public.m12_06_list_filtered_feed_atomic(p_org,p_actor,p_filters->>'eventClass',(p_filters->>'windowStart')::timestamptz,(p_filters->>'batchId')::uuid,v_cursor,50); else select outcome,result into v_outcome,v_result from public.list_notification_feed_atomic(p_org,p_actor,p_filters->>'category',p_filters->>'severity',coalesce(p_filters->>'read','all'),v_cursor,50); end if;
  if v_outcome not in ('found','listed','previewed','ok') or v_result is null then raise exception 'export_source_%',coalesce(v_outcome,'unavailable') using errcode='42501'; end if;
