  end loop;
  v_next:=v_result->>'nextCursor'; if v_next is null then exit; end if;
  if v_cursor=v_next then raise exception 'export_source_cursor_cycle' using errcode='22023'; end if;
  v_cursor:=v_next; v_offset:=v_offset+100;
  if v_total>=100001 then exit; end if;
 end loop; return;
