 return query select r.id::text, encode(extensions.digest((jsonb_build_object('id',r.id,'identifier',r.identifier,'displayName',r.display_name,'legalName',r.legal_name,'mainEstablishmentCountry',r.main_establishment_country,'manufacturerContactName',r.manufacturer_contact_name,'manufacturerContactEmail',r.manufacturer_contact_email,'phone',r.phone,'registrationIdentifier',r.registration_identifier,'taxIdentifier',r.tax_identifier,'completionStatus',r.completion_status,'status',r.status,'isDefault',r.is_default,'version',r.version,'createdAt',r.created_at,'updatedAt',r.updated_at))::text,'sha256'),'hex'),null::uuid,jsonb_build_object('id',r.id,'identifier',r.identifier,'displayName',r.display_name,'legalName',r.legal_name,'mainEstablishmentCountry',r.main_establishment_country,'manufacturerContactName',r.manufacturer_contact_name,'manufacturerContactEmail',r.manufacturer_contact_email,'phone',r.phone,'registrationIdentifier',r.registration_identifier,'taxIdentifier',r.tax_identifier,'completionStatus',r.completion_status,'status',r.status,'isDefault',r.is_default,'version',r.version,'createdAt',r.created_at,'updatedAt',r.updated_at) from public.m14_03_legal_entity_rows(p_org) r  where r.organization_id=p_org  order by r.is_default desc,r.display_name,r.id limit 100001; return;
when 'organization.retention_policies' then
 return query select r.id::text, encode(extensions.digest((jsonb_build_object('id',r.id,'evidenceClass',r.evidence_class,'version',r.version,'requestedRetentionDays',r.requested_retention_days,'effectiveFloorDays',r.effective_floor_days,'effectiveRetentionDays',r.effective_retention_days,'floorSnapshotVersion',r.floor_snapshot_version,'updatedAt',r.updated_at))::text,'sha256'),'hex'),null::uuid,jsonb_build_object('id',r.id,'evidenceClass',r.evidence_class,'version',r.version,'requestedRetentionDays',r.requested_retention_days,'effectiveFloorDays',r.effective_floor_days,'effectiveRetentionDays',r.effective_retention_days,'floorSnapshotVersion',r.floor_snapshot_version,'updatedAt',r.updated_at) from public.organization_retention_policies r  where r.organization_id=p_org  order by r.evidence_class limit 100001; return;
