 return query select h.item::text,r.version::text,null::uuid,jsonb_build_object('date',h.item::text) from public.organization_settings r cross join lateral unnest(r.holidays) with ordinality h(item,n) where r.organization_id=p_org order by h.n limit 100001; return;
