 return query select coalesce(q.item->>'recordId',(q.item->>'kind')||':'||q.n::text),r.version::text,null::uuid,q.item from public.organization_lifecycles r cross join lateral jsonb_array_elements(public.m1_normalize_lifecycle_blockers(r.purge_block_reasons)) with ordinality q(item,n) where r.organization_id=p_org order by q.n limit 100001; return;
