 return query select r.stage, encode(extensions.digest((jsonb_build_object('stage',r.stage,'status',r.status,'blockReason',r.block_reason,'completedAt',r.completed_at,'completedBy',r.completed_by,'updatedAt',r.updated_at))::text,'sha256'),'hex'),null::uuid,jsonb_build_object('stage',r.stage,'status',r.status,'blockReason',r.block_reason,'completedAt',r.completed_at,'completedBy',r.completed_by,'updatedAt',r.updated_at) from public.organization_onboarding_stages r  where r.organization_id=p_org  order by r.stage_order limit 100001; return;
