when 'frameworks.coverage_requirements' then
 return query select r.requirement_key,coalesce(c.computed_revision::text,'unavailable'),v_product,jsonb_build_object('requirementKey',r.requirement_key,'identifier',r.identifier,'heading',r.heading,'text',r.text,'parentKey',r.parent_requirement_key,'coverageState',case when c.status='current' and c.source_revision=c.computed_revision and v.computed_revision=c.computed_revision then v.status else 'unavailable' end,'calculationStatus',case when c.status='current' and c.source_revision=c.computed_revision and v.computed_revision=c.computed_revision then 'current' when c.status is null then 'unavailable' else 'stale' end,'sourceRevision',c.source_revision,'computedRevision',c.computed_revision) from public.framework_requirements r join public.m14_03_framework_pack_rows(p_org) fp using(pack_key,version_key) left join public.framework_coverage_scopes c on c.organization_id=p_org and c.product_id=v_product and c.pack_key=r.pack_key and c.version_key=r.version_key left join public.framework_coverage_rows v on v.organization_id=p_org and v.product_id=v_product and v.pack_key=r.pack_key and v.version_key=r.version_key and v.requirement_key=r.requirement_key where r.pack_key=p_context->>'packKey' and r.version_key=p_context->>'versionKey' and (fp.owner_org_id is null or fp.owner_org_id=p_org) and (coalesce(p_filters->>'filter','all')='all' or c.status is distinct from 'current' or c.source_revision is distinct from c.computed_revision or v.computed_revision is distinct from c.computed_revision or case p_filters->>'filter' when 'excluded' then v.status='excluded' when 'evidence_backed' then v.status='evidence_backed' else v.status not in ('structural','excluded','evidence_backed') end) order by r.tree_order limit 100001; return;
else return query select * from public.m14_03_additional_source_rows(p_org,p_actor,p_source,p_filters,p_context); end case;
end $$;
create function public.m14_03_operational_source_rows(p_org uuid,p_actor uuid,p_source text,p_filters jsonb,p_context jsonb) returns table(source_id text,source_version text,product_id uuid,row_values jsonb) language sql stable security definer set search_path=public,pg_temp as $$ select source_id,source_version,product_id,public.m14_03_operational_projection(row_values,public.m14_03_source_policy(p_source)->'columns') from public.m14_03_operational_source_rows_unprojected(p_org,p_actor,p_source,p_filters,p_context) offset case when p_context->>'_exportScope'='current_page' and p_filters->>'cursor' is null then greatest(0,(coalesce((p_filters->>'page')::integer,1)-1)*coalesce((p_filters->>'pageSize')::integer,(p_filters->>'limit')::integer,25)) else 0 end $$;
