create function public.m14_03_operational_snapshot_access(p_job public.export_jobs) returns boolean
language plpgsql stable security definer set search_path=public,pg_temp as $$
declare v_keys jsonb; v_filters jsonb;
begin
 if not public.m14_03_job_access(p_job) then return false; end if;
 if p_job.source='notifications.chat_channels' and not public.m12_05_chat_admin(p_job.organization_id,p_job.requester_id) then return false; end if;
 case p_job.source
 when 'connectors.instances' then return not exists(select 1 from public.export_snapshot_rows r where r.organization_id=p_job.organization_id and r.job_id=p_job.id and not exists(select 1 from public.connectors x where x.organization_id=p_job.organization_id and x.id::text=r.source_id ));
 when 'connectors.overview' then return not exists(select 1 from public.export_snapshot_rows r where r.organization_id=p_job.organization_id and r.job_id=p_job.id and not exists(select 1 from public.connectors x where x.organization_id=p_job.organization_id and x.id::text=r.source_id ));
 when 'connectors.identities' then return not exists(select 1 from public.export_snapshot_rows r where r.organization_id=p_job.organization_id and r.job_id=p_job.id and not exists(select 1 from public.product_external_identities x where x.organization_id=p_job.organization_id and x.id::text=r.source_id and x.connector_id=(p_job.context->>'connectorId')::uuid and x.superseded_at is null));
 when 'connectors.sync_runs' then return not exists(select 1 from public.export_snapshot_rows r where r.organization_id=p_job.organization_id and r.job_id=p_job.id and not exists(select 1 from public.sync_runs x where x.organization_id=p_job.organization_id and x.id::text=r.source_id and x.connector_id=(p_job.context->>'connectorId')::uuid));
 when 'connectors.sync_history' then return not exists(select 1 from public.export_snapshot_rows r where r.organization_id=p_job.organization_id and r.job_id=p_job.id and not exists(select 1 from public.sync_runs x where x.organization_id=p_job.organization_id and x.id::text=r.source_id and x.connector_id=(p_job.context->>'connectorId')::uuid));
 when 'connectors.dead_letters' then return not exists(select 1 from public.export_snapshot_rows r where r.organization_id=p_job.organization_id and r.job_id=p_job.id and not exists(select 1 from public.sync_runs x where x.organization_id=p_job.organization_id and x.id::text=r.source_id and x.connector_id=(p_job.context->>'connectorId')::uuid));
 when 'connectors.sync_records' then return not exists(select 1 from public.export_snapshot_rows r where r.organization_id=p_job.organization_id and r.job_id=p_job.id and not exists(select 1 from public.sync_run_plan_items x where x.organization_id=p_job.organization_id and x.id::text=r.source_id and x.sync_run_id=(p_job.context->>'syncRunId')::uuid));
 when 'connectors.sync_plan_items' then return not exists(select 1 from public.export_snapshot_rows r where r.organization_id=p_job.organization_id and r.job_id=p_job.id and not exists(select 1 from public.sync_run_plan_items x where x.organization_id=p_job.organization_id and x.id::text=r.source_id and x.sync_run_id=(p_job.context->>'syncRunId')::uuid));
 when 'connectors.run_conflicts' then return not exists(select 1 from public.export_snapshot_rows r where r.organization_id=p_job.organization_id and r.job_id=p_job.id and not exists(select 1 from public.sync_conflicts x where x.organization_id=p_job.organization_id and x.id::text=r.source_id and x.sync_run_id=(p_job.context->>'syncRunId')::uuid));
 when 'connectors.sync_run_attempts' then return not exists(select 1 from public.export_snapshot_rows r where r.organization_id=p_job.organization_id and r.job_id=p_job.id and not exists(select 1 from public.sync_run_attempts x where x.organization_id=p_job.organization_id and x.id::text=r.source_id and x.sync_run_id=(p_job.context->>'syncRunId')::uuid));
 when 'connectors.dead_letter_records' then return not exists(select 1 from public.export_snapshot_rows r where r.organization_id=p_job.organization_id and r.job_id=p_job.id and not exists(select 1 from public.sync_run_plan_items x where x.organization_id=p_job.organization_id and x.id::text=r.source_id and exists(select 1 from public.sync_runs z where z.organization_id=x.organization_id and z.id=x.sync_run_id and z.connector_id=(p_job.context->>'connectorId')::uuid)));
 when 'connectors.agent_batches' then return not exists(select 1 from public.export_snapshot_rows r where r.organization_id=p_job.organization_id and r.job_id=p_job.id and not exists(select 1 from public.connector_agent_batches x where x.organization_id=p_job.organization_id and x.id::text=r.source_id and x.connector_id=(p_job.context->>'connectorId')::uuid));
 when 'connectors.webhook_endpoints' then return not exists(select 1 from public.export_snapshot_rows r where r.organization_id=p_job.organization_id and r.job_id=p_job.id and not exists(select 1 from public.webhook_endpoints x where x.organization_id=p_job.organization_id and x.id::text=r.source_id ));
 when 'connectors.webhook_deliveries' then return not exists(select 1 from public.export_snapshot_rows r where r.organization_id=p_job.organization_id and r.job_id=p_job.id and not exists(select 1 from public.webhook_deliveries x where x.organization_id=p_job.organization_id and x.id::text=r.source_id and x.endpoint_id=(p_job.context->>'endpointId')::uuid));
 when 'connectors.webhook_attempts' then return not exists(select 1 from public.export_snapshot_rows r where r.organization_id=p_job.organization_id and r.job_id=p_job.id and not exists(select 1 from public.webhook_delivery_attempts x where x.organization_id=p_job.organization_id and x.id::text=r.source_id and x.delivery_row_id=(p_job.context->>'deliveryId')::uuid));
 when 'connectors.siem_destinations' then return not exists(select 1 from public.export_snapshot_rows r where r.organization_id=p_job.organization_id and r.job_id=p_job.id and not exists(select 1 from public.siem_destinations x where x.organization_id=p_job.organization_id and x.id::text=r.source_id ));
 when 'frameworks.controls' then return not exists(select 1 from public.export_snapshot_rows r where r.organization_id=p_job.organization_id and r.job_id=p_job.id and not exists(select 1 from public.framework_controls x where x.organization_id=p_job.organization_id and x.id::text=r.source_id ));
 when 'frameworks.custom' then return not exists(select 1 from public.export_snapshot_rows r where r.organization_id=p_job.organization_id and r.job_id=p_job.id and not exists(select 1 from public.framework_custom_pack_drafts x where x.organization_id=p_job.organization_id and x.id::text=r.source_id ));
 when 'notifications.burst_batches' then return not exists(select 1 from public.export_snapshot_rows r where r.organization_id=p_job.organization_id and r.job_id=p_job.id and not exists(select 1 from public.notification_digest_batches x where x.organization_id=p_job.organization_id and x.id::text=r.source_id and x.batch_kind='burst'));
 when 'notifications.chat_channels' then return not exists(select 1 from public.export_snapshot_rows r where r.organization_id=p_job.organization_id and r.job_id=p_job.id and not exists(select 1 from public.notification_chat_channels x where x.organization_id=p_job.organization_id and x.id::text=r.source_id ));
 when 'notifications.chat_deliveries' then return not exists(select 1 from public.export_snapshot_rows r where r.organization_id=p_job.organization_id and r.job_id=p_job.id and not exists(select 1 from public.notification_chat_deliveries x where x.organization_id=p_job.organization_id and x.id::text=r.source_id ));
 when 'organization.legal_entities' then return not exists(select 1 from public.export_snapshot_rows r where r.organization_id=p_job.organization_id and r.job_id=p_job.id and not exists(select 1 from public.organization_legal_entities x where x.organization_id=p_job.organization_id and x.id::text=r.source_id ));
 when 'organization.retention_policies' then return not exists(select 1 from public.export_snapshot_rows r where r.organization_id=p_job.organization_id and r.job_id=p_job.id and not exists(select 1 from public.organization_retention_policies x where x.organization_id=p_job.organization_id and x.id::text=r.source_id ));
 when 'organization.tenant_exports' then return not exists(select 1 from public.export_snapshot_rows r where r.organization_id=p_job.organization_id and r.job_id=p_job.id and not exists(select 1 from public.organization_export_jobs x where x.organization_id=p_job.organization_id and x.id::text=r.source_id ));
 when 'onboarding.progress' then return not exists(select 1 from public.export_snapshot_rows r where r.organization_id=p_job.organization_id and r.job_id=p_job.id and not exists(select 1 from public.organization_onboarding_stages x where x.organization_id=p_job.organization_id and x.stage::text=r.source_id ));

 when 'connectors.siem_deliveries' then return not exists(select 1 from public.export_snapshot_rows r
 where r.organization_id=p_job.organization_id and r.job_id=p_job.id and not exists(select 1
 from public.siem_deliveries d join public.siem_destinations s on s.organization_id=d.organization_id and s.id=d.destination_id
 join public.audit_logs a on a.organization_id=d.organization_id and a.id=d.event_id
 where d.organization_id=p_job.organization_id and d.id::text=r.source_id and d.destination_id=(p_job.context->>'destinationId')::uuid
 and public.m13_05_event_selected(p_job.organization_id,p_job.requester_id,a,s.product_ids)));
 when 'notifications.feed' then
 -- Individual items are rechecked against source-owned self-scoped feed authority.
 -- Group aggregate scope is version-sensitive; source permission changes invalidate the job upstream.
 return not exists(select 1 from public.export_snapshot_rows r where r.organization_id=p_job.organization_id and r.job_id=p_job.id
 and (case when r.source_id like 'batch|%' then r.source_version is distinct from public.m14_03_feed_group_scope(p_job.organization_id,p_job.requester_id,split_part(r.source_id,'|',2),split_part(r.source_id,'|',3)::timestamptz,split_part(r.source_id,'|',4),nullif(split_part(r.source_id,'|',5),''),p_job.snapshot_as_of) else not exists(select 1 from public.m12_06_feed_rows(p_job.organization_id,p_job.requester_id) f where f.ref=r.source_id) end));
 when 'notifications.feed_preview_items' then return not exists(select 1 from public.export_snapshot_rows r where r.organization_id=p_job.organization_id and r.job_id=p_job.id
 and not exists(select 1 from public.m12_06_feed_rows(p_job.organization_id,p_job.requester_id) f where f.ref=r.source_id and r.source_version=public.m14_03_feed_group_scope(p_job.organization_id,p_job.requester_id,p_job.context->>'eventClass',(p_job.context->>'windowStartsAt')::timestamptz,f.category,p_job.filters->>'severity',p_job.snapshot_as_of)));
 when 'notifications.deliveries' then return not exists(select 1 from public.export_snapshot_rows r where r.organization_id=p_job.organization_id and r.job_id=p_job.id and not (
 exists(select 1 from public.notification_dispatches d where d.organization_id=p_job.organization_id and d.id::text=r.source_id)
 or exists(select 1 from public.product_regulatory_outbox_events d join public.products p on p.organization_id=d.organization_id and p.id=d.product_id where d.organization_id=p_job.organization_id and 'm2_'||d.id::text=r.source_id and d.event_type='support_period.alert')
 or exists(select 1 from public.reporting_deadline_alert_deliveries d where d.organization_id=p_job.organization_id and 'm6_'||d.id::text=r.source_id)));
 when 'frameworks.catalog' then return not exists(select 1 from public.export_snapshot_rows r where r.organization_id=p_job.organization_id and r.job_id=p_job.id and not exists(select 1 from public.framework_pack_versions f where f.pack_key||':'||f.version_key=r.source_id and (f.owner_org_id is null or f.owner_org_id=p_job.organization_id)));
 when 'frameworks.requirement_tree' then return public.m10_custom_pack_visible(p_job.organization_id,p_job.context->>'packKey',p_job.context->>'versionKey');
 when 'frameworks.coverage_requirements' then return public.m10_custom_pack_visible(p_job.organization_id,p_job.context->>'packKey',p_job.context->>'versionKey') and exists(select 1 from public.products p where p.organization_id=p_job.organization_id and p.id=coalesce((p_job.context->>'productId')::uuid,(p_job.filters->>'productId')::uuid) and p.archived_at is null);
 when 'frameworks.custom_requirements_preview' then return exists(select 1 from public.framework_custom_pack_drafts d where d.organization_id=p_job.organization_id and d.id=(p_job.context->>'draftId')::uuid);
 when 'frameworks.crosswalks' then return not exists(select 1 from public.export_snapshot_rows r where r.organization_id=p_job.organization_id and r.job_id=p_job.id and not exists(select 1 from public.framework_curated_crosswalks c where c.id::text=r.source_id and c.retired_at is null and public.m10_custom_pack_visible(p_job.organization_id,c.source_pack_key,c.source_version_key) and public.m10_custom_pack_visible(p_job.organization_id,c.target_pack_key,c.target_version_key)));
 when 'frameworks.upgrade_preview' then return not exists(select 1 from public.export_snapshot_rows r where r.organization_id=p_job.organization_id and r.job_id=p_job.id and not exists(select 1 from public.framework_control_requirement_mappings m where m.organization_id=p_job.organization_id and m.id::text=r.source_id));
 when 'frameworks.upgrade_review' then return exists(select 1 from public.framework_upgrade_reviews v where v.organization_id=p_job.organization_id and v.id=(p_job.context->>'reviewId')::uuid and v.pack_key=p_job.context->>'packKey');
 when 'organization.holidays' then return true;
 when 'organization.lifecycle_blockers' then return true;
 when 'connectors.catalogue' then return true;
 when 'permissions.matrix' then return true;
 else return public.m14_03_additional_snapshot_access(p_job);
 end case;
end $$;

do $grants$ declare f record; begin
 for f in select p.oid::regprocedure signature from pg_proc p where p.pronamespace='public'::regnamespace
 and (p.proname like 'm14_03_%_rows' or p.proname in ('m14_03_operational_source_rows','m14_03_operational_source_rows_unprojected','m14_03_operational_snapshot_access','m14_03_feed_group_scope','m14_03_operational_projection','m14_03_source_policy','m14_03_core_source_policy')) loop
 execute format('revoke all on function %s from public,anon,authenticated',f.signature);
 execute format('grant execute on function %s to service_role',f.signature);
 end loop; end $grants$;
